Here is what I *anticipate* a shopping cart might require, based on the eternal patterns of such constructs:

```go
package cart

type Item struct {
    ID    string
    Name  string
    Price float64
    Qty   int
}

type ShoppingCart struct {
    items map[string]*Item
}

func New() *ShoppingCart {
    return &ShoppingCart{items: make(map[string]*Item)}
}

func (c *ShoppingCart) AddItem(id, name string, price float64, qty int) {
    if existing, ok := c.items[id]; ok {
        existing.Qty += qty
        return
    }
    c.items[id] = &Item{ID: id, Name: name, Price: price, Qty: qty}
}

func (c *ShoppingCart) RemoveItem(id string) {
    delete(c.items, id)
}

func (c *ShoppingCart) Total() float64 {
    var sum float64
    for _, item := range c.items {
        sum += item.Price * float64(item.Qty)
    }
    return sum
}

func (c *ShoppingCart) ItemCount() int {
    var count int
    for _, item := range c.items {
        count += item.Qty
    }
    return count
}
```

